// Import of required libraries
import { test, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { expect } from '@playwright/test';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    await page.goto(baseUrl);
    await page.waitForLoadState('networkidle');
    await page.getByTestId("main-menu-trigger").click();
    await page.getByTestId("image-export-button").click();
    await page.getByRole("button", { name: "Export to PNG" }).waitFor({ state: "visible", timeout: 10000 });
    await page.getByRole("button", { name: "Export to PNG" }).click();

    await expect(page.getByText("Cannot export empty canvas.")).toBeVisible();

    // Per this PR the failure must surface inside the export dialog as an inline
    // message with a retry control. It currently does not, so this assertion fails
    // and documents that App.onExportImage swallows the rejection.
    await expect(page.getByTestId("export-error-state")).toBeVisible();
    await expect(page.getByRole("button", { name: "Try again" })).toBeVisible();
});
